package com.unicare.dispensary.screening;
import com.unicare.dispensary.student.Student;import jakarta.persistence.*;import java.time.LocalDate;import java.time.LocalDateTime;
@Entity @Table(name="health_screenings",indexes=@Index(name="idx_screening_student",columnList="student_id"))
public class HealthScreening{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="student_id",nullable=false)private Student student;@Column(nullable=false)private LocalDate screeningDate;@Column(length=300)private String allergies;@Column(length=500)private String conditions;@Column(length=500)private String currentMedication;@Column(nullable=false,length=12)private String wellbeing;@Column(length=1000)private String symptoms;@Column(length=1000)private String notes;@Column(nullable=false)private LocalDateTime createdAt;protected HealthScreening(){}public HealthScreening(Student s,LocalDate d,String a,String c,String m,String w,String symptoms,String notes){student=s;screeningDate=d;allergies=a;conditions=c;currentMedication=m;wellbeing=w;this.symptoms=symptoms;this.notes=notes;}@PrePersist void onCreate(){createdAt=LocalDateTime.now();}public Long getId(){return id;}public Student getStudent(){return student;}public LocalDate getScreeningDate(){return screeningDate;}public String getAllergies(){return allergies;}public String getConditions(){return conditions;}public String getCurrentMedication(){return currentMedication;}public String getWellbeing(){return wellbeing;}public String getSymptoms(){return symptoms;}public String getNotes(){return notes;}public LocalDateTime getCreatedAt(){return createdAt;}}
